      endDate: period === 'month' ? `${selectedCalendarDay.slice(0, 7)}-${String(new Date(Number(selectedCalendarDay.slice(0, 4)), Number(selectedCalendarDay.slice(5, 7)), 0).getDate()).padStart(2, '0')}` : selectedCalendarDay,
      employeeSearch: '',
